/** The brief's sale name for the board's own ("Memorial Day"), in the line that
 *  says it: the whole name where the line says "SALE" too, else without it
 *  ("MEMORIAL DAY" over "SALE"); the rest of the line kept ("… FAVORITES");
 *  capitals where the board's are. */
const SALE_NAME = /\bMemorial\s+Day(\s+sale)?\b/i;
const named = (title: string, board: string) => board.replace(SALE_NAME, (said, sale) => {
  const t = sale ? title : title.replace(/\s*sale\s*$/i, '');
  return said === said.toUpperCase() ? t.toUpperCase() : t;
});

